<?php
require_once __DIR__ . '/../includes/functions.php';
$learner = require_role('user');
$onlinePaymentsAvailable = project_env('PAYMONGO_ENABLED') === 'true'
    && str_starts_with(project_env('PAYMONGO_SECRET_KEY'), 'sk_test_');
$stmt = db()->prepare('SELECT a.id, a.booking_date, a.session_time, a.end_time, a.meeting_place, a.meeting_latitude, a.meeting_longitude, a.contact_info, a.status, a.notes, a.rejection_reason, a.agreed_rate, a.completion_confirmed_at, a.completion_issue, t.full_name AS tutor_name, c.course_code, c.course_name, r.id AS review_id, p.status AS payment_status, p.payment_method, p.checkout_url FROM appointments a JOIN users t ON t.id = a.tutor_id JOIN courses c ON c.id = a.course_id LEFT JOIN session_reviews r ON r.appointment_id = a.id LEFT JOIN appointment_payments p ON p.appointment_id = a.id WHERE a.learner_id = ? ORDER BY a.booking_date DESC, a.session_time DESC, a.created_at DESC');
$stmt->bind_param('i', $learner['id']);
$stmt->execute();
$sessions = $stmt->get_result();
$total = $sessions->num_rows;
$applicationStmt = db()->prepare('SELECT status, admin_note FROM tutor_applications WHERE learner_id = ?');
$applicationStmt->bind_param('i', $learner['id']);
$applicationStmt->execute();
$tutorApplication = $applicationStmt->get_result()->fetch_assoc();
$applicationStmt->close();
$pageTitle = 'My Sessions';
require __DIR__ . '/../includes/header.php';
?>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4"><div><p class="text-uppercase text-primary fw-semibold small mb-1">Learner space</p><h1 class="page-heading h2 mb-1">My sessions</h1><p class="text-muted mb-0">Welcome, <?= e($learner['full_name']) ?>. You have <?= $total ?> session request(s).</p></div><div class="d-flex gap-2"><a class="btn btn-primary" href="<?= e(url('user/tutors.php')) ?>">Find a tutor</a><form method="post" action="<?= e(url('logout.php')) ?>"><?= csrf_field() ?><button class="btn btn-outline-secondary" type="submit">Log out</button></form></div></div>
<div class="card mb-4"><div class="card-body d-flex justify-content-between align-items-center flex-wrap gap-3"><div><h2 class="h5 mb-1">Interested in tutoring?</h2><?php if (!$tutorApplication): ?><p class="text-muted mb-0">Apply to share your knowledge with other learners. An administrator will review your application.</p><?php else: ?><p class="text-muted mb-0">Application status: <?= e(ucfirst(strtolower($tutorApplication['status']))) ?>.<?php if ($tutorApplication['status'] === 'REJECTED' && $tutorApplication['admin_note']): ?> Review note: <?= e($tutorApplication['admin_note']) ?><?php endif; ?></p><?php endif; ?></div><?php if (!$tutorApplication || $tutorApplication['status'] === 'REJECTED'): ?><a class="btn btn-outline-primary" href="<?= e(url('user/tutor_application.php')) ?>"><?= $tutorApplication ? 'Update application' : 'Apply as tutor' ?></a><?php endif; ?></div></div>
<?php if ($total === 0): ?><div class="card"><div class="card-body text-center py-5"><h2 class="h5">No sessions yet</h2><p class="text-muted">Browse tutors and send your first request.</p><a class="btn btn-primary" href="<?= e(url('user/tutors.php')) ?>">Browse tutors</a></div></div><?php else: ?>
<div class="row g-3"><?php while ($row = $sessions->fetch_assoc()): ?><?php $meetingMapUrl = meeting_map_url($row['meeting_latitude'], $row['meeting_longitude']); ?><div class="col-lg-6"><article class="card h-100"><div class="card-body"><div class="d-flex justify-content-between gap-3"><div><div class="text-muted small"><?= e($row['course_code']) ?></div><h2 class="h5 mb-1"><?= e($row['course_name']) ?></h2></div><?= status_badge($row['status']) ?></div><p class="mt-3 mb-1"><strong>Tutor:</strong> <?= e($row['tutor_name']) ?></p><p class="mb-1"><strong>When:</strong> <?= e(format_date($row['booking_date'])) ?> · <?= e(format_time($row['session_time'])) ?>–<?= e(format_time($row['end_time'])) ?></p><?php if ($row['meeting_place']): ?><p class="mb-1"><strong>Meeting place:</strong> <?= e($row['meeting_place']) ?><?php if ($meetingMapUrl): ?> · <a href="<?= e($meetingMapUrl) ?>" target="_blank" rel="noopener">Open map</a><?php endif; ?></p><?php endif; ?><?php if ($row['contact_info']): ?><p class="mb-1"><strong>Your contact:</strong> <?= e($row['contact_info']) ?></p><?php endif; ?><?php if ($row['notes']): ?><p class="text-muted small mt-2 mb-0"><?= e($row['notes']) ?></p><?php endif; ?><?php if ($row['status'] === 'CANCELLED' && $row['rejection_reason']): ?><div class="alert alert-warning mt-3 mb-0"><strong>Tutor's reason:</strong> <?= e($row['rejection_reason']) ?></div><?php endif; ?>
<?php if ($row['status'] === 'COMPLETED' && $row['completion_issue']): ?><div class="alert alert-warning mt-3 mb-0"><strong>Reported issue awaiting admin review:</strong> <?= e($row['completion_issue']) ?></div>
<?php elseif ($row['status'] === 'COMPLETED' && !$row['completion_confirmed_at']): ?><div class="border rounded p-3 mt-3"><p class="mb-2">The tutor marked this session complete. Confirm the session to continue to payment, or report a problem.</p><form method="post" action="<?= e(url('user/confirm_session.php')) ?>" class="d-flex flex-wrap gap-2 mb-2"><?= csrf_field() ?><input type="hidden" name="appointment_id" value="<?= (int) $row['id'] ?>"><button class="btn btn-sm btn-success" name="action" value="confirm" type="submit">Confirm session</button></form><form method="post" action="<?= e(url('user/confirm_session.php')) ?>"><?= csrf_field() ?><input type="hidden" name="appointment_id" value="<?= (int) $row['id'] ?>"><label class="form-label small" for="issue-<?= (int) $row['id'] ?>">Report a problem</label><textarea class="form-control form-control-sm mb-2" id="issue-<?= (int) $row['id'] ?>" name="completion_issue" minlength="10" maxlength="500" rows="2" placeholder="Describe what needs review"></textarea><button class="btn btn-sm btn-outline-danger" name="action" value="report" type="submit">Send report</button></form></div>
<?php elseif ($row['status'] === 'COMPLETED' && $row['completion_confirmed_at'] && $row['payment_status'] === 'PAID'): ?><p class="small text-success mt-3 mb-0">Payment received.</p>
<?php elseif ($row['status'] === 'COMPLETED' && $row['completion_confirmed_at']): ?><?php $durationMinutes = (int) ((strtotime($row['end_time']) - strtotime($row['session_time'])) / 60); $sessionTotal = (float) $row['agreed_rate'] * $durationMinutes / 60; ?><?php if ((float) $row['agreed_rate'] > 0 && $durationMinutes > 0): ?><p class="mt-3 mb-2"><strong>Amount due:</strong> PHP <?= e(number_format($sessionTotal, 2)) ?> <span class="text-muted small">(PHP <?= e(number_format((float) $row['agreed_rate'], 2)) ?>/hour)</span></p><?php if ($row['payment_status'] === 'PENDING' && $row['payment_method'] === 'CASH'): ?><p class="small text-warning mb-0">Cash in person selected. The tutor will confirm once they receive payment.</p><?php elseif ($row['payment_status'] === 'PENDING' && $row['payment_method'] === 'PAYMONGO' && $onlinePaymentsAvailable): ?><form method="post" action="<?= e(url('user/pay_session.php')) ?>"><?= csrf_field() ?><input type="hidden" name="appointment_id" value="<?= (int) $row['id'] ?>"><button class="btn btn-sm btn-primary" type="submit">Continue to online payment</button></form><?php elseif (!$row['payment_status']): ?><p class="small text-muted mb-2"><?= $onlinePaymentsAvailable ? 'Choose how you’ll pay:' : 'Cash only is available right now.' ?></p><div class="d-flex flex-wrap gap-2"><?php if ($onlinePaymentsAvailable): ?><form method="post" action="<?= e(url('user/pay_session.php')) ?>"><?= csrf_field() ?><input type="hidden" name="appointment_id" value="<?= (int) $row['id'] ?>"><button class="btn btn-sm btn-primary" type="submit">Pay online</button></form><?php endif; ?><form method="post" action="<?= e(url('user/pay_cash.php')) ?>"><?= csrf_field() ?><input type="hidden" name="appointment_id" value="<?= (int) $row['id'] ?>"><button class="btn btn-sm btn-outline-primary" type="submit">Cash in person</button></form></div><?php endif; ?><?php else: ?><p class="text-warning small mt-3 mb-0">The approved session rate is missing. Please contact an administrator.</p><?php endif; ?><?php endif; ?>
<?php if ($row['status'] === 'COMPLETED' && !$row['review_id']): ?><a class="btn btn-sm btn-outline-primary mt-3" href="<?= e(url('user/review.php?appointment_id=' . (int) $row['id'])) ?>">Rate this session</a><?php elseif ($row['review_id']): ?><span class="small text-success d-block mt-3">Review submitted</span><?php endif; ?></div></article></div><?php endwhile; ?></div>
<?php endif; ?>
<?php require __DIR__ . '/../includes/footer.php'; ?>
